"""Generate the ORE script library dataset from ORE's scriptlibrary.xml.

The methodology is step 5 of external/ore/methodology.txt. In order:

1. extract every script of the library, with its variants, results,
   calibrations and schedule coarsenings, and the comment block that
   precedes it;
2. apply the corrections of script_library_corrections.json, each of which
   must find its text exactly once, or find its replacement already there;
3. parse every variant with the shell's `script check`, which fails on a
   script that does not parse;
4. derive every script's inputs with the shell's `script inputs`, merging its
   variants.

It writes the dataset's methodology, dataset and artefact populate files.
With --check it writes nothing and fails when the committed files differ from
what it makes.
"""

import argparse
import json
import subprocess
import sys
import tempfile
import xml.etree.ElementTree as ET
from dataclasses import dataclass, field
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
LIBRARY = ROOT / "external/ore/examples/Products/Input/scriptlibrary.xml"
CORRECTIONS = Path(__file__).resolve().parent / "script_library_corrections.json"
METHODOLOGY = ROOT / "external/ore/methodology.txt"
OUT_DIR = ROOT / "projects/ores.sql/populate/ore"
DEFAULT_SHELL = ROOT / "build/output/linux-clang-release-ninja/publish/bin/ores.shell"

DATASET_CODE = "ore.script_library"
METHODOLOGY_NAME = "ORE GitHub Extraction"
ARTEFACT_TYPE = "script_library"
INPUT_HEADINGS = ("Input Data:", "Inputs:")
# Every heading the library's comments use. A line that ends in a colon and is
# not one of them, such as a sentence, is text and ends no section.
SECTION_HEADINGS = INPUT_HEADINGS + ("Result Data:", "Results:", "Requirements:")
# The as-of date of the dataset: change it when the library is regenerated from
# a newer ORE commit, so the dataset states when its rows were taken.
AS_OF = "2026-11-21"

LICENSE = """/* -*- sql-product: postgres; tab-width: 4; indent-tabs-mode: nil -*-
 *
 * Copyright (C) 2026 Marco Craveiro <marco.craveiro@gmail.com>
 *
 * This program is free software; you can redistribute it and/or modify it under
 * the terms of the GNU General Public License as published by the Free Software
 * Foundation; either version 3 of the License, or (at your option) any later
 * version.
 *
 * This program is distributed in the hope that it will be useful, but WITHOUT
 * ANY WARRANTY; without even the implied warranty of MERCHANTABILITY or FITNESS
 * FOR A PARTICULAR PURPOSE. See the GNU General Public License for more
 * details.
 *
 * You should have received a copy of the GNU General Public License along with
 * this program; if not, write to the Free Software Foundation, Inc., 51
 * Franklin Street, Fifth Floor, Boston, MA 02110-1301, USA.
 *
 */
/* Generated by external/ore/tools/generate_script_library.py from ORE's script
 * library. Do not edit: follow step 5 of external/ore/methodology.txt. */
"""


class GenerationError(Exception):
    pass


@dataclass
class Variant:
    purpose: str
    code: str
    npv: str
    results: list = field(default_factory=list)
    calibrations: list = field(default_factory=list)
    coarsenings: list = field(default_factory=list)


@dataclass
class Script:
    name: str
    product_tag: str | None
    description: str | None
    input_descriptions: dict
    variants: list
    inputs: list = field(default_factory=list)


def comment_description(comment):
    """The first line of a script's comment block, and its inputs' texts."""
    if comment is None:
        return None, {}
    lines = comment.splitlines()
    first = next((line.strip() for line in lines if line.strip()), None)
    descriptions = {}
    in_inputs = False
    for line in lines:
        text = line.strip()
        if text in SECTION_HEADINGS:
            in_inputs = text in INPUT_HEADINGS
            continue
        if not in_inputs or not text:
            continue
        # An entry is a name and its text, separated by spaces or tabs. A line
        # that continues a description is read the same way, and is looked up
        # only if it starts with one of the script's input names, so the first
        # entry of a name is the one kept.
        name, *rest = text.split(None, 1)
        descriptions.setdefault(name, rest[0].strip() if rest else None)
    return first, descriptions


def read_variant(element, purpose):
    code = element.findtext("Code")
    npv = element.findtext("NPV")
    if code is None or npv is None:
        raise GenerationError(f"a {purpose} variant states no Code or no NPV")
    variant = Variant(purpose=purpose, code=code, npv=npv.strip())
    for result in element.findall("Results/Result"):
        variant.results.append((result.text.strip(), result.get("rename")))
    for calibration in element.findall("CalibrationSpec/Calibration"):
        strikes = [s.text.strip() for s in calibration.findall("Strikes/Strike")]
        variant.calibrations.append((calibration.findtext("Index").strip(), strikes))
    for schedule in element.findall("ScheduleCoarsening/EligibleSchedule"):
        variant.coarsenings.append(schedule.text.strip())
    return variant


def extract(path):
    """Every script of the library, in the library's order."""
    parser = ET.XMLParser(target=ET.TreeBuilder(insert_comments=True))
    root = ET.parse(path, parser=parser).getroot()
    scripts = []
    comment = None
    for child in root:
        if child.tag is ET.Comment:
            comment = child.text
            continue
        if child.tag != "Script":
            continue
        name = child.findtext("Name").strip()
        tag = child.findtext("ProductTag")
        description, inputs = comment_description(comment)
        variants = []
        for element in child.findall("Script"):
            variants.append(read_variant(element, element.get("purpose", "default")))
        if not variants:
            raise GenerationError(f"script {name} states no variant")
        scripts.append(Script(name, tag.strip() if tag else None, description, inputs, variants))
        comment = None
    return scripts


def correct(scripts, corrections):
    """Apply each correction once, or confirm it is already applied."""
    by_key = {(s.name, v.purpose): v for s in scripts for v in s.variants}
    for c in corrections:
        variant = by_key.get((c["script"], c["purpose"]))
        if variant is None:
            raise GenerationError(f"the correction of {c['script']} ({c['purpose']}) "
                                  "finds no script variant")
        found = variant.code.count(c["text"])
        if found == 0 and c["replacement"] in variant.code:
            continue
        if found != 1:
            raise GenerationError(f"the correction of {c['script']} ({c['purpose']}) finds "
                                  f"its text {found} times; if ORE's library changed the "
                                  "script, review the correction")
        variant.code = variant.code.replace(c["text"], c["replacement"])


def unescape(field_text):
    out, i = [], 0
    while i < len(field_text):
        c = field_text[i]
        if c == "\\" and i + 1 < len(field_text):
            escaped = {"\\": "\\", "t": "\t", "r": "\r", "n": "\n"}.get(field_text[i + 1])
            if escaped is None:
                raise GenerationError(f"the shell wrote an unknown escape in {field_text!r}")
            out.append(escaped)
            i += 2
        else:
            out.append(c)
            i += 1
    return "".join(out)


def derive_inputs(scripts, shell):
    """Parse every variant and derive every script's inputs with the shell."""
    with tempfile.TemporaryDirectory(prefix="ores_script_library_") as work:
        work = Path(work)
        commands = []
        for s in scripts:
            files = []
            for v in s.variants:
                path = work / f"{s.name}.{v.purpose}.txt"
                path.write_text(v.code, encoding="utf-8")
                files.append(str(path))
                commands.append(f"script check {path}")
            commands.append(f"script inputs {' '.join(files)} --out {work / (s.name + '.tsv')}")
        batch = work / "derive.ores"
        batch.write_text("\n".join(commands) + "\n", encoding="utf-8")
        run = subprocess.run(
            [str(shell), "--nats-url", "nats://127.0.0.1:1", "--load", str(batch)],
            capture_output=True, text=True, check=False)
        if run.returncode != 0:
            raise GenerationError("the shell refused a script:\n" + run.stdout + run.stderr)
        for s in scripts:
            for line in (work / f"{s.name}.tsv").read_text(encoding="utf-8").splitlines():
                name, data_type, is_array, rule = (unescape(f) for f in line.split("\t"))
                s.inputs.append((name, data_type, is_array == "1", rule or None))


def literal(value):
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    return "'" + value.replace("'", "''") + "'"


def code_literal(code):
    if "$code$" in code:
        raise GenerationError("a script's code holds the $code$ quote")
    return "$code$" + code + "$code$"


def insert(table, columns, rows):
    if not rows:
        return ""
    head = (f"    insert into ores_dq_{table}_artefact_tbl (\n"
            f"        dataset_id, tenant_id, version, {', '.join(columns)}\n"
            "    ) values\n")
    body = ",\n".join(
        "        (v_dataset_id, ores_utility_system_tenant_id_fn(), 0, " + ", ".join(row) + ")"
        for row in rows)
    return head + body + ";\n\n"


def render_artefacts(scripts):
    rows = {k: [] for k in ("scripts", "script_variants", "script_results", "script_calibrations",
                            "script_calibration_strikes", "script_coarsenings", "script_inputs")}
    for s in scripts:
        name = literal(s.name)
        rows["scripts"].append([name, literal(s.product_tag), literal(s.description)])
        for v in s.variants:
            purpose = literal(v.purpose)
            rows["script_variants"].append([name, purpose, code_literal(v.code), literal(v.npv)])
            for n, (variable, rename) in enumerate(v.results, 1):
                rows["script_results"].append(
                    [name, purpose, literal(n), literal(variable), literal(rename)])
            for n, (index, strikes) in enumerate(v.calibrations, 1):
                rows["script_calibrations"].append([name, purpose, literal(n), literal(index)])
                for m, strike in enumerate(strikes, 1):
                    rows["script_calibration_strikes"].append(
                        [name, purpose, literal(n), literal(m), literal(strike)])
            for n, schedule in enumerate(v.coarsenings, 1):
                rows["script_coarsenings"].append([name, purpose, literal(n), literal(schedule)])
        for n, (input_name, data_type, is_array, rule) in enumerate(s.inputs, 1):
            rows["script_inputs"].append(
                [name, literal(n), literal(input_name), literal(data_type), literal(is_array),
                 literal(rule), literal(s.input_descriptions.get(input_name))])

    columns = {
        "scripts": ["name", "product_tag", "description"],
        "script_variants": ["script_name", "purpose", "code", "npv_variable"],
        "script_results": ["script_name", "purpose", "sequence_number", "variable", "rename"],
        "script_calibrations": ["script_name", "purpose", "sequence_number", "index_variable"],
        "script_calibration_strikes": ["script_name", "purpose", "calibration_number",
                                       "sequence_number", "strike_variable"],
        "script_coarsenings": ["script_name", "purpose", "sequence_number", "eligible_schedule"],
        "script_inputs": ["script_name", "sequence_number", "input_name", "data_type", "is_array",
                          "value_rule", "description"],
    }
    deletes = "".join(f"    delete from ores_dq_{t}_artefact_tbl where dataset_id = v_dataset_id;\n"
                      for t in reversed(list(rows)))
    inserts = "".join(insert(t, columns[t], rows[t]) for t in rows)
    return (LICENSE + "\n\\echo '--- ORE script library artefacts ---'\n\n"
            "do $body$\ndeclare\n    v_dataset_id uuid;\nbegin\n"
            "    select id into v_dataset_id from ores_dq_datasets_tbl\n"
            f"    where code = '{DATASET_CODE}'\n"
            "      and valid_to = ores_utility_infinity_timestamp_fn();\n"
            "    if v_dataset_id is null then\n"
            f"        raise exception 'Dataset {DATASET_CODE} not found. Run dataset population "
            "first.';\n    end if;\n\n" + deletes + "\n" + inserts.rstrip("\n") + "\nend\n$body$;\n")


def render_methodology(text):
    return (LICENSE + "\n\\echo '--- ORE methodology ---'\n\n"
            "select ores_dq_methodologies_upsert_fn(ores_utility_system_tenant_id_fn(),\n"
            f"    {literal(METHODOLOGY_NAME)},\n"
            "    'Data extracted from the ORE GitHub project at the commit the repository "
            "carries',\n"
            "    'https://github.com/OpenSourceRisk/Engine',\n"
            "    " + literal(text) + ");\n")


def render_dataset(scripts):
    return (LICENSE + "\n\\echo '--- ORE script library dataset ---'\n\n"
            "select ores_dq_datasets_upsert_fn(ores_utility_system_tenant_id_fn(),\n"
            f"    {literal(DATASET_CODE)},\n"
            "    'ORE',\n    'General',\n    'Reference Data',\n    'NONE',\n"
            "    'Primary',\n    'Actual',\n    'Raw',\n"
            f"    {literal(METHODOLOGY_NAME)},\n"
            "    'ORE Script Library',\n"
            f"    {literal(f'The {len(scripts)} payoff scripts of the library ORE distributes, with their variants, results, calibrations and inputs, as ORE Studio parses and corrects them.')},\n"
            "    'ORE',\n"
            "    'The payoff scripts every scripted trade names.',\n"
            f"    '{AS_OF}'::date,\n"
            "    'Modified BSD License',\n"
            f"    {literal(ARTEFACT_TYPE)});\n")


def outputs(shell):
    scripts = extract(LIBRARY)
    correct(scripts, json.loads(CORRECTIONS.read_text(encoding="utf-8")))
    derive_inputs(scripts, shell)
    return {
        OUT_DIR / "ore_methodology_populate.sql":
            render_methodology(METHODOLOGY.read_text(encoding="utf-8")),
        OUT_DIR / "ore_script_library_dataset_populate.sql": render_dataset(scripts),
        OUT_DIR / "ore_script_library_artefact_populate.sql": render_artefacts(scripts),
    }, scripts


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--shell", default=str(DEFAULT_SHELL),
                        help="the built ores.shell (default: %(default)s)")
    parser.add_argument("--check", action="store_true",
                        help="write nothing; fail when a committed file differs")
    args = parser.parse_args(argv)
    shell = Path(args.shell)
    if not shell.is_file():
        print(f"error: no ores.shell at {shell}; build it first (compass build ores.shell)",
              file=sys.stderr)
        return 1
    try:
        files, scripts = outputs(shell)
    except GenerationError as e:
        print(f"error: {e}", file=sys.stderr)
        return 1
    if args.check:
        stale = [p for p, text in files.items()
                 if not p.exists() or p.read_text(encoding="utf-8") != text]
        for p in stale:
            print(f"{p.relative_to(ROOT)} differs from what the generator makes; "
                  "run external/ore/tools/generate_script_library.py", file=sys.stderr)
        return 1 if stale else 0
    for p, text in files.items():
        p.write_text(text, encoding="utf-8")
        print(f"wrote {p.relative_to(ROOT)}")
    print(f"scripts={len(scripts)} variants={sum(len(s.variants) for s in scripts)} "
          f"inputs={sum(len(s.inputs) for s in scripts)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
